class Solution {
    public int trap(int[] height) {
        int max_left = 0;
        int L = 1;
        int R = height.length-2;
        int max_right = 0;
        int res = 0;
        while(L<=R){
            if(height[L-1]<height[R+1]){
                max_left = Math.max(max_left,height[L-1]);
                int min = max_left;
                if(min>height[L]){
                    res+=min-height[L];
                }
                L++;
            }else{
                max_right = Math.max(max_right,height[R+1]);
                int min = max_right;
                if(min>height[R]){
                    res+=min-height[R];
                }
                R--;
            }
        }
        return res;
    }
}
